Here is the commit message:
genirq/debugfs: Add missing sanity checks to interrupt
 injection

Interrupts cannot be injected when the interrupt is not activated and when
a replay is already in progress.

Fixes: 536e2e34bd00 ("genirq/debugfs: Triggering of interrupts from userspace")
Signed-off-by: Thomas Gleixner <tglx@linutronix.de>
Acked-by: Marc Zyngier <maz@kernel.org>
Cc: stable@vger.kernel.org
Link: https://lkml.kernel.org/r/20200306130623.500019114@linutronix.de

Here is the root cause:
The bug arises from the lack of proper checks before allowing interrupt injection, specifically failing to verify if the interrupt is activated or if a replay is already in progress. This oversight can lead to invalid states where interrupts are injected when they should not be, such as during level or NMI types, potentially causing system instability or unexpected behavior.

Here is the patch:

 static ssize_t irq_debug_write(struct file *file, const char __user *user_buf,
 			       size_t count, loff_t *ppos)
 {
 	struct irq_desc *desc = file_inode(file)->i_private;
 	char buf[8] = { 0, };
 	size_t size;

 	size = min(sizeof(buf) - 1, count);
 	if (copy_from_user(buf, user_buf, size))
 		return -EFAULT;

 	if (!strncmp(buf, "trigger", size)) {
 		unsigned long flags;
 		int err;

 		/* Try the HW interface first */
 		err = irq_set_irqchip_state(irq_desc_get_irq(desc),
 					    IRQCHIP_STATE_PENDING, true);
 		if (!err)
 			return count;

 		/*
 		 * Otherwise, try to inject via the resend interface,
 		 * which may or may not succeed.
 		 */
 		chip_bus_lock(desc);
 		raw_spin_lock_irqsave(&desc->lock, flags);

-		if (irq_settings_is_level(desc) || desc->istate & IRQS_NMI) {
-			/* Can't do level nor NMIs, sorry */
+		/*
+		 * Don't allow injection when the interrupt is:
+		 *  - Level or NMI type
+		 *  - not activated
+		 *  - replaying already
+		 */
+		if (irq_settings_is_level(desc) ||
+		    !irqd_is_activated(&desc->irq_data) ||
+		    (desc->istate & (IRQS_NMI | IRQS_REPLAY))) {
 			err = -EINVAL;
 		} else {
 			desc->istate |= IRQS_PENDING;
 			check_irq_resend(desc);
 			err = 0;
 		}

 		raw_spin_unlock_irqrestore(&desc->lock, flags);
 		chip_bus_sync_unlock(desc);

 		return err ? err : count;
 	}

 	return count;
 }



